public class SubmitEnablerPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    public static void main(String[] args) {
        try {
            SubmitEnablerPanel panel = new SubmitEnablerPanel();
            java.awt.Component fieldComp = find(panel, "entry");
            java.awt.Component buttonComp = find(panel, "submit");
            check("entry field found", true, fieldComp instanceof javax.swing.JTextField);
            check("submit button found", true, buttonComp instanceof javax.swing.JButton);
            if (fieldComp instanceof javax.swing.JTextField && buttonComp instanceof javax.swing.JButton) {
                javax.swing.JTextField entry = (javax.swing.JTextField) fieldComp;
                javax.swing.JButton submit = (javax.swing.JButton) buttonComp;
                check("disabled while empty at startup", false, submit.isEnabled());
                entry.setText("report");
                check("enabled after typing", true, submit.isEnabled());
                entry.setText("     ");
                check("spaces only counts as empty", false, submit.isEnabled());
                entry.setText("  x  ");
                check("padded text still counts", true, submit.isEnabled());
                entry.setText("");
                check("disabled again after clearing", false, submit.isEnabled());
            } else {
                failures++;
                System.out.println("FAIL  entry or submit not found by name");
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

