import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;

public class SubmitEnablerPanel extends JPanel {

    private final JTextField entry = new JTextField(12);
    private final JButton submit = new JButton("Submit");

    public SubmitEnablerPanel() {
        entry.setName("entry");
        submit.setName("submit");
        add(entry);
        add(submit);
        entry.getDocument().addDocumentListener(new DocumentListener() {
            public void insertUpdate(DocumentEvent e) {
                refreshSubmitState();
            }

            public void removeUpdate(DocumentEvent e) {
                refreshSubmitState();
            }

            public void changedUpdate(DocumentEvent e) {
                refreshSubmitState();
            }
        });
        refreshSubmitState();
    }

    private void refreshSubmitState() {
        String typed = entry.getText().trim();
        submit.setEnabled(!typed.isEmpty());
    }
}
